function formatDate(value) { return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(new Date(value)); }
function sourceDetails(url, hasImage = false) { if (!url) return { type: hasImage ? "image" : "note", label: hasImage ? "Screenshot" : "Saved text" }; try { const parsed = new URL(url); const host = parsed.hostname.replace(/^www\./, ""); return { type: host.includes("youtube.com") || host === "youtu.be" ? "article" : "article", label: host }; } catch { return { type: "note", label: "Saved text" }; } }
function notify(message) { els.toast.textContent = message; els.toast.classList.add("show"); clearTimeout(notify.timer); notify.timer = setTimeout(() => els.toast.classList.remove("show"), 2500); }
function titleCase(value = "") { return value.replace(/[-_]/g, " ").replace(/\b\w/g, char => char.toUpperCase()); }
function countMatches(text, words) { return words.reduce((score, word) => score + (text.includes(word) ? (word.includes(" ") ? 3 : 1) : 0), 0); }
function classify(text = "") { const haystack = text.toLowerCase(); const scores = Object.fromEntries(Object.entries(CATEGORY_RULES).map(([key, words]) => [key, countMatches(haystack, words)])); const category = Object.entries(scores).sort((a, b) => b[1] - a[1])[0]?.[1] ? Object.entries(scores).sort((a, b) => b[1] - a[1])[0][0] : "life"; const children = CATEGORIES[category].children; const subcategory = children.map(key => [key, countMatches(haystack, SUBCATEGORY_RULES[key] || [])]).sort((a, b) => b[1] - a[1])[0]; return { category, subcategory: subcategory?.[1] ? subcategory[0] : children[0] }; }
function normaliseRecord(record) { const assigned = CURATED_CLASSIFICATION[record.id]; const inferred = classify([record.title, record.quote, record.note, record.content, ...(record.tags || [])].filter(Boolean).join(" ")); return { ...record, category: record.category || assigned?.[0] || inferred.category, subcategory: record.subcategory || assigned?.[1] || inferred.subcategory, bucket: record.bucket || "saved", tags: record.tags || [], createdAt: Number(record.createdAt) || Date.now(), updatedAt: Number(record.updatedAt) || Date.now() }; }

function weekSeed() { const now = new Date(); const utc = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()); return Math.floor((utc + 259200000) / 604800000); }
function seededScore(value) { let hash = 2166136261; for (const char of value) { hash ^= char.codePointAt(0); hash = Math.imul(hash, 16777619); } return hash >>> 0; }
function weeklyRecords() { const seed = weekSeed(); return [...state.records].sort((a, b) => seededScore(`${seed}:${a.id}`) - seededScore(`${seed}:${b.id}`)).slice(0, 5); }
function filteredRecords() { const q = state.query.trim().toLowerCase(); const weekly = new Set(weeklyRecords().map(record => record.id)); return state.records.filter(record => { const source = sourceDetails(record.url, Boolean(record.image)); const inView = state.view === "all" || state.view === "weekly" && weekly.has(record.id) || record.category === state.view; const inSub = !state.subcategory || record.subcategory === state.subcategory; const inSource = state.source === "all" || source.type === state.source; const haystack = [record.title, record.quote, record.note, record.relevance, record.resonance, record.content, record.url, record.sourceLabel, record.category, record.subcategory, ...(record.tags || [])].filter(Boolean).join(" ").toLowerCase(); return inView && inSub && inSource && (!q || haystack.includes(q)); }).sort((a, b) => state.newest ? b.createdAt - a.createdAt : a.createdAt - b.createdAt); }

function renderNavigation() {
  $("#categoryNav").innerHTML = Object.entries(CATEGORIES).map(([key, config]) => { const count = state.records.filter(record => record.category === key).length; const childButtons = config.children.map(child => `<button class="subnav-item ${state.subcategory === child ? "active" : ""}" data-category="${key}" data-subcategory="${child}" type="button"><span>${titleCase(child)}</span><b>${state.records.filter(record => record.category === key && record.subcategory === child).length}</b></button>`).join(""); return `<div class="category-row ${state.view === key ? "open" : ""}"><button class="category-trigger ${state.view === key && !state.subcategory ? "active" : ""}" data-view="${key}" type="button"><span class="nav-symbol">${config.symbol}</span><span class="category-name">${config.label}</span><b>${count}</b><span class="category-caret">›</span></button><div class="subnav"><div>${childButtons}</div></div></div>`; }).join("");
  $("#mobileCategoryGrid").innerHTML = Object.entries(CATEGORIES).map(([key, config]) => `<section class="more-category"><button class="more-parent" data-more-view="${key}" type="button">${config.symbol} ${config.label}</button><div class="more-topics">${config.children.map(child => `<button data-more-category="${key}" data-more-sub="${child}" type="button">${titleCase(child)}</button>`).join("")}</div></section>`).join("");
  bindNavigation();
}
function bindNavigation() { $$('[data-view]').forEach(button => button.onclick = () => setView(button.dataset.view)); $$('[data-subcategory]').forEach(button => button.onclick = event => { event.stopPropagation(); setView(button.dataset.category, button.dataset.subcategory); }); $$('[data-more-view]').forEach(button => button.onclick = () => { els.more.close(); setView(button.dataset.moreView); }); $$('[data-more-sub]').forEach(button => button.onclick = () => { els.more.close(); setView(button.dataset.moreCategory, button.dataset.moreSub); }); }
function setView(view, subcategory = "") { state.view = view; state.subcategory = subcategory; state.source = "all"; $$('[data-source]').forEach(button => button.classList.toggle("active", button.dataset.source === "all")); $$('[data-view]').forEach(button => button.classList.toggle("active", button.dataset.view === view && !subcategory)); $$('[data-mobile-view]').forEach(button => button.classList.toggle("active", button.dataset.mobileView === view)); const config = view === "all" ? ["Everything worth keeping.", "Your archive"] : view === "weekly" ? ["Worth meeting again.", "Resurface"] : [subcategory ? titleCase(subcategory) : CATEGORIES[view].label, subcategory ? `${CATEGORIES[view].label} · nested view` : "Category"]; els.title.textContent = config[0]; els.eyebrow.textContent = config[1]; renderNavigation(); render(); }

function render() {
  const records = filteredRecords();
  els.grid.innerHTML = records.map((record, index) => { const source = sourceDetails(record.url, Boolean(record.image)); const tags = record.tags.slice(0, 2).map(tag => `<span class="tag">#${escapeHtml(tag)}</span>`).join(""); const image = record.image ? `<img class="card-image" src="${escapeHtml(record.image)}" alt="Saved screenshot" />` : ""; const note = record.relevance || record.note; return `<article class="fragment-card" data-id="${escapeHtml(record.id)}" tabindex="0" style="animation-delay:${Math.min(index * 35, 245)}ms"><div class="card-source"><span class="source-name">${record.url ? "↗ " : record.image ? "⌗ " : "— "}${escapeHtml(record.sourceLabel || source.label)}</span><span class="category-pill">${escapeHtml(record.category)} · ${escapeHtml(record.subcategory)}</span></div>${record.title ? `<h2 class="article-card-title">${escapeHtml(record.title)}</h2>` : ""}<span class="quote-mark">“</span><blockquote>${escapeHtml(record.quote || "Saved for later")}</blockquote>${note ? `<p class="card-note">${escapeHtml(note)}</p>` : ""}${record.resonance ? `<p class="resonance-line">“${escapeHtml(record.resonance)}”</p>` : ""}${image}<div class="card-bottom">${tags}<span class="card-date">${formatDate(record.createdAt)}</span></div></article>`; }).join("");
  els.grid.hidden = records.length === 0; els.empty.hidden = records.length !== 0; els.count.textContent = `${records.length} ${records.length === 1 ? "item" : "items"}`; $("#allCount").textContent = state.records.length; const weeklyNode = $('[data-count="weekly"]'); if (weeklyNode) weeklyNode.textContent = weeklyRecords().length;
  $$(".fragment-card").forEach(card => { card.onclick = () => openDetail(card.dataset.id); card.onkeydown = event => { if (["Enter", " "].includes(event.key)) { event.preventDefault(); openDetail(card.dataset.id); } }; });
}

function openDetail(id) { const record = state.records.find(item => item.id === id); if (!record) return; state.currentId = id; $("#detailMeta").textContent = `${record.category} · ${record.subcategory} · ${record.sourceLabel || sourceDetails(record.url, Boolean(record.image)).label}`; $("#detailTitle").textContent = record.title || "Saved fragment"; $("#detailThesis").textContent = record.quote || record.content || "Saved for later"; $("#detailRelevance").textContent = record.relevance || record.note || "This was kept for you to revisit and connect later."; $("#detailResonance").textContent = record.resonance || bestSentence(record.content || record.quote || ""); $("#detailTags").innerHTML = record.tags.map(tag => `<span>#${escapeHtml(tag)}</span>`).join(""); const href = safeUrl(record.url); $("#detailLink").hidden = !href; if (href) $("#detailLink").href = href; $("#deleteRecord").hidden = Boolean(record.curated); els.detail.showModal(); }

function resetCapture() { els.form.reset(); state.files = []; $("#fileCount").textContent = ""; $("#imageHelp").textContent = "Text is read privately on this device"; $("#ocrProgress").hidden = true; $("#ocrBar").style.width = "0%"; els.queue.hidden = true; els.queue.innerHTML = ""; els.error.hidden = true; els.save.disabled = false; els.save.textContent = "Digest & save"; }
function openCapture() { resetCapture(); els.capture.showModal(); setTimeout(() => els.links.focus(), 30); }
function closeCapture() { els.capture.close(); }
function parseLinks(value) { const candidates = value.split(/(?=https?:\/\/)/gi).map(item => item.trim()).filter(Boolean); const urls = []; for (const item of candidates) { const match = item.match(/^https?:\/\/[^\s]+/i); if (!match) continue; const cleaned = match[0].replace(/[),.;]+$/, ""); const url = safeUrl(cleaned); if (url && !urls.includes(url)) urls.push(url); } return urls.slice(0, 30); }
function stripMarkdown(text = "") { return text.replace(/^Title:.*$/gim, "").replace(/^URL Source:.*$/gim, "").replace(/^Published Time:.*$/gim, "").replace(/^Markdown Content:\s*$/gim, "").replace(/!\[[^\]]*\]\([^)]*\)/g, " ").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/[`#>*_~|]/g, " ").replace(/\s+/g, " ").trim(); }
function bestSentence(text = "") { const clean = stripMarkdown(text); const sentences = clean.match(/[^.!?]+[.!?]+/g) || [clean]; return (sentences.find(sentence => { const words = sentence.trim().split(/\s+/).length; return words >= 8 && words <= 34; }) || sentences[0] || "Saved to revisit.").trim().slice(0, 300); }
function extractiveSummary(text = "") { const clean = stripMarkdown(text).slice(0, 30000); if (!clean) return "Saved to revisit."; const sentences = (clean.match(/[^.!?]+[.!?]+/g) || [clean]).map(item => item.trim()).filter(item => item.length > 45 && item.length < 420).slice(0, 80); if (!sentences.length) return clean.slice(0, 420); const frequency = {}; clean.toLowerCase().match(/[a-z][a-z'-]{3,}/g)?.forEach(word => { if (!STOP_WORDS.has(word)) frequency[word] = (frequency[word] || 0) + 1; }); const ranked = sentences.map((sentence, index) => ({ sentence, index, score: (sentence.toLowerCase().match(/[a-z][a-z'-]{3,}/g) || []).reduce((total, word) => total + (frequency[word] || 0), 0) / Math.max(sentence.length, 1) + (index < 4 ? .15 : 0) })).sort((a, b) => b.score - a.score).slice(0, 2).sort((a, b) => a.index - b.index); return ranked.map(item => item.sentence).join(" ").slice(0, 700); }
function autoTags(text = "") { const counts = {}; stripMarkdown(text).toLowerCase().match(/[a-z][a-z'-]{3,}/g)?.forEach(word => { if (!STOP_WORDS.has(word)) counts[word] = (counts[word] || 0) + 1; }); return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([word]) => word); }
function relevanceFor(category, subcategory, summary) { const leads = { life: "This belongs with the ideas shaping how you live and relate to people.", god: "This connects belief to the way you actually live, question, and choose.", tech: "This can sharpen what you build, learn, or lead—not just what you know about.", history: "This gives present choices a longer memory and a wider frame.", science: "This rewards testing the explanation instead of merely accepting the label." }; return `${leads[category]} In ${titleCase(subcategory)}, the thread worth revisiting is: ${bestSentence(summary)}`; }
async function prepareSummarizer() { try { if (!("Summarizer" in window)) return null; const availability = await Summarizer.availability(); if (availability === "unavailable") return null; return await Summarizer.create({ type: "tldr", format: "plain-text", length: "medium", monitor(monitor) { monitor.addEventListener("downloadprogress", event => { els.queue.hidden = false; els.queue.innerHTML = `<p>Preparing the private AI reader… ${Math.round(event.loaded * 100)}%</p>`; }); } }); } catch { return null; } }
async function makeDigest(text) { if (state.summarizer) { try { const result = await state.summarizer.summarize(stripMarkdown(text).slice(0, 28000)); if (result?.trim()) return result.trim().slice(0, 900); } catch { /* use the reliable local fallback */ } } return extractiveSummary(text); }
async function readArticle(url) { const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), 22000); try { const response = await fetch(`https://r.jina.ai/${url}`, { signal: controller.signal, headers: { Accept: "text/plain" } }); if (!response.ok) throw new Error("Could not read source"); const raw = (await response.text()).slice(0, 120000); const title = raw.match(/^Title:\s*(.+)$/im)?.[1]?.trim() || new URL(url).hostname.replace(/^www\./, ""); return { title, content: raw }; } finally { clearTimeout(timeout); } }
async function processLink(url, manualTags) { let title = new URL(url).hostname.replace(/^www\./, ""); let content = ""; let readError = false; try { const article = await readArticle(url); title = article.title; content = article.content; } catch { readError = true; } const digest = content ? await makeDigest(content) : "Saved for later. This source blocked automatic reading, but the original link is intact."; const classification = classify(`${title} ${content}`); const tags = [...new Set([...manualTags, ...autoTags(`${title} ${content}`)])].slice(0, 8); return normaliseRecord({ id: crypto.randomUUID(), title, quote: digest, relevance: relevanceFor(classification.category, classification.subcategory, digest), resonance: content ? bestSentence(content) : "The source is preserved even when the page cannot be read automatically.", content: stripMarkdown(content).slice(0, 40000), url, sourceLabel: new URL(url).hostname.replace(/^www\./, ""), category: classification.category, subcategory: classification.subcategory, tags, image: "", bucket: "saved", readError, createdAt: Date.now(), updatedAt: Date.now() }); }
async function fileToDataUrl(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); }
async function readScreenshot(file, position, total) { let worker; try { if (!window.Tesseract?.createWorker) throw new Error("OCR unavailable"); worker = await Tesseract.createWorker("eng", 1, { workerPath: new URL("./ocr/worker.min.js", location.href).href, corePath: new URL("./ocr/tesseract-core-lstm.wasm.js", location.href).href, langPath: new URL("./ocr", location.href).href.replace(/\/$/, ""), gzip: true, logger(message) { const percent = Math.round((message.progress || 0) * 100); $("#ocrProgress").hidden = false; $("#ocrBar").style.width = `${percent}%`; $("#imageHelp").textContent = `Reading image ${position} of ${total} · ${percent}%`; } }); const result = await worker.recognize(file); return result?.data?.text?.replace(/\n{3,}/g, "\n\n").trim() || ""; } finally { if (worker) await worker.terminate(); } }
