async function processPlainText(text, manualTags) { const digest = await makeDigest(text); const classification = classify(text); return normaliseRecord({ id: crypto.randomUUID(), title: "Saved text", quote: digest, relevance: relevanceFor(classification.category, classification.subcategory, digest), resonance: bestSentence(text), content: text.slice(0, 40000), url: "", sourceLabel: "Saved text", category: classification.category, subcategory: classification.subcategory, tags: [...new Set([...manualTags, ...autoTags(text)])].slice(0, 8), image: "", bucket: "saved", createdAt: Date.now(), updatedAt: Date.now() }); }
async function saveCapture(event) { event.preventDefault(); const urls = parseLinks(els.links.value); const plainText = els.text.value.trim(); const manualTags = els.tags.value.split(",").map(tag => tag.trim().replace(/^#/, "").toLowerCase()).filter(Boolean).slice(0, 8); if (!urls.length && !state.files.length && !plainText) { els.error.textContent = "Add at least one link, screenshot, or piece of text."; els.error.hidden = false; return; } els.error.hidden = true; els.save.disabled = true; els.save.textContent = "Working…"; els.queue.hidden = false; state.summarizer = await prepareSummarizer(); const saved = []; try { for (let index = 0; index < urls.length; index += 3) { const batch = urls.slice(index, index + 3); els.queue.innerHTML = `<p>Reading links ${index + 1}–${Math.min(index + batch.length, urls.length)} of ${urls.length}…</p>`; const records = await Promise.all(batch.map(url => processLink(url, manualTags))); for (const record of records) { await putRecord(record); saved.push(record); } } for (let index = 0; index < state.files.length; index++) { els.queue.innerHTML = `<p>Transcribing screenshot ${index + 1} of ${state.files.length}…</p>`; const record = await processImage(state.files[index], manualTags, index + 1, state.files.length); await putRecord(record); saved.push(record); } if (plainText) { els.queue.innerHTML = "<p>Digesting pasted text…</p>"; const record = await processPlainText(plainText, manualTags); await putRecord(record); saved.push(record); } if (state.session) await syncRecords(saved); state.records = (await allRecords()).map(normaliseRecord); renderNavigation(); render(); closeCapture(); notify(`${saved.length} ${saved.length === 1 ? "item" : "items"} read, sorted, and saved`); } catch (error) { els.error.textContent = error?.message || "Some items could not be processed. Anything completed is still saved."; els.error.hidden = false; } finally { els.save.disabled = false; els.save.textContent = "Digest & save"; if (state.summarizer?.destroy) state.summarizer.destroy(); state.summarizer = null; } }

function cloudReady() { return /^https:\/\/.+\.supabase\.co$/i.test(cloudConfig.supabaseUrl || "") && Boolean(cloudConfig.supabasePublishableKey); }
function sessionHeaders(json = true) { return { apikey: cloudConfig.supabasePublishableKey, ...(json ? { "Content-Type": "application/json" } : {}), ...(state.session?.access_token ? { Authorization: `Bearer ${state.session.access_token}` } : {}) }; }
async function cloudRequest(path, options = {}) { const response = await fetch(`${cloudConfig.supabaseUrl}${path}`, { ...options, headers: { ...sessionHeaders(options.json !== false), ...(options.headers || {}) } }); const text = await response.text(); let body = null; if (text) { try { body = JSON.parse(text); } catch { body = { message: text }; } } if (!response.ok) throw new Error(body?.msg || body?.message || body?.error_description || "Cloud request failed"); return body; }
function saveSession(session) { state.session = session; if (session) localStorage.setItem("commentary-cloud-session", JSON.stringify(session)); else localStorage.removeItem("commentary-cloud-session"); renderAccount(); }
async function authenticate(mode) { const email = $("#accountEmail").value.trim(); const password = $("#accountPassword").value; const error = $("#accountError"); if (!email || !password) { error.textContent = "Enter your email and password."; error.hidden = false; return; } error.hidden = true; try { const path = mode === "signup" ? "/auth/v1/signup" : "/auth/v1/token?grant_type=password"; const session = await cloudRequest(path, { method: "POST", body: JSON.stringify({ email, password }) }); if (!session?.access_token) { error.textContent = "Check your inbox to confirm the account, then sign in."; error.hidden = false; return; } saveSession(session); await syncAll(); els.account.close(); notify("Archive synced across devices"); } catch (caught) { error.textContent = caught.message; error.hidden = false; } }
async function refreshSession() { if (!cloudReady()) return; try { const stored = JSON.parse(localStorage.getItem("commentary-cloud-session") || "null"); if (!stored?.refresh_token) return; state.session = stored; const session = await cloudRequest("/auth/v1/token?grant_type=refresh_token", { method: "POST", body: JSON.stringify({ refresh_token: stored.refresh_token }) }); saveSession(session); await syncAll(); } catch { saveSession(null); } }
function toCloud(record) { return { id: record.id, title: record.title || "", quote: record.quote || "", note: record.note || "", relevance: record.relevance || "", resonance: record.resonance || "", content: record.content || "", url: record.url || "", source_label: record.sourceLabel || "", category: record.category, subcategory: record.subcategory, tags: record.tags, bucket: record.bucket, curated: Boolean(record.curated), read_error: Boolean(record.readError), created_at: new Date(record.createdAt).toISOString(), updated_at: new Date(record.updatedAt).toISOString() }; }
function fromCloud(row) { return normaliseRecord({ id: row.id, title: row.title, quote: row.quote, note: row.note, relevance: row.relevance, resonance: row.resonance, content: row.content, url: row.url, sourceLabel: row.source_label, category: row.category, subcategory: row.subcategory, tags: row.tags || [], bucket: row.bucket, curated: row.curated, readError: row.read_error, image: "", imagePath: row.image_path || "", createdAt: Date.parse(row.created_at), updatedAt: Date.parse(row.updated_at) }); }
async function uploadImage(record) { if (!record.image?.startsWith("data:") || !state.session?.user?.id) return record.imagePath || ""; const [header, data] = record.image.split(","); const mime = header.match(/data:([^;]+)/)?.[1] || "image/jpeg"; const bytes = Uint8Array.from(atob(data), char => char.charCodeAt(0)); const extension = mime.split("/")[1]?.replace("jpeg", "jpg") || "jpg"; const path = `${state.session.user.id}/${record.id}.${extension}`; const response = await fetch(`${cloudConfig.supabaseUrl}/storage/v1/object/captures/${path}`, { method: "POST", headers: { ...sessionHeaders(false), "Content-Type": mime, "x-upsert": "true" }, body: bytes }); if (!response.ok) throw new Error("Screenshot upload failed"); return path; }
async function signedImage(path) { if (!path) return ""; try { const result = await cloudRequest(`/storage/v1/object/sign/captures/${path}`, { method: "POST", body: JSON.stringify({ expiresIn: 3600 }) }); return result?.signedURL ? `${cloudConfig.supabaseUrl}/storage/v1${result.signedURL}` : ""; } catch { return ""; } }
async function syncRecords(records) { if (!state.session || !records.length) return; const rows = []; for (const record of records) { const imagePath = await uploadImage(record); rows.push({ ...toCloud(record), image_path: imagePath }); } await cloudRequest("/rest/v1/fragments?on_conflict=user_id%2Cid", { method: "POST", headers: { Prefer: "resolution=merge-duplicates,return=minimal" }, body: JSON.stringify(rows) }); }
async function syncAll() { if (!state.session) return; $("#saveState").textContent = "Syncing…"; await syncRecords(state.records); const rows = await cloudRequest("/rest/v1/fragments?select=*"); for (const row of rows || []) { const record = fromCloud(row); if (record.imagePath) record.image = await signedImage(record.imagePath); await putRecord(record); } state.records = (await allRecords()).map(normaliseRecord); $("#saveState").textContent = "Synced"; renderNavigation(); render(); }
function renderAccount() { const ready = cloudReady(); $("#accountSetup").hidden = ready; $("#accountFields").hidden = !ready || Boolean(state.session); $("#signedInPanel").hidden = !state.session; if (state.session) { $("#signedInEmail").textContent = state.session.user?.email || "your account"; $("#syncTitle").textContent = "Synced"; $("#syncSubtitle").textContent = state.session.user?.email || "Cloud archive"; $("#syncOrb").classList.add("online"); } else { $("#syncTitle").textContent = ready ? "Cloud sync" : "This device"; $("#syncSubtitle").textContent = ready ? "Sign in across devices" : "Private local archive"; $("#syncOrb").classList.remove("online"); } }

async function exportArchive() { const payload = { app: "Commentary Archive", version: 2, exportedAt: new Date().toISOString(), fragments: state.records }; const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = `commentary-archive-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(link.href); notify("Backup downloaded"); }
async function importArchive(file) { try { const payload = JSON.parse(await file.text()); if (!Array.isArray(payload.fragments)) throw new Error(); const imported = []; for (const item of payload.fragments) { if (!item.id || !(item.quote || item.content)) continue; const record = normaliseRecord(item); await putRecord(record); imported.push(record); } if (state.session) await syncRecords(imported); state.records = (await allRecords()).map(normaliseRecord); els.data.close(); renderNavigation(); render(); notify(`${imported.length} items restored`); } catch { notify("That backup could not be read"); } }
async function updateStorageLine() { if (!navigator.storage?.estimate) return; const { usage = 0, quota = 0 } = await navigator.storage.estimate(); $("#storageLine").textContent = `${(usage / 1024 / 1024).toFixed(1)} MB used · ${Math.round(quota / 1024 / 1024)} MB available on this device`; navigator.storage.persist?.(); }

function registerWebMcp() { const context = document.modelContext; if (!context?.registerTool) return; try { context.registerTool({ name: "capture_fragment", title: "Capture a fragment", description: "Save text or a source link and automatically classify it.", inputSchema: { type: "object", properties: { text: { type: "string" }, url: { type: "string" }, tags: { type: "array", items: { type: "string" } } }, additionalProperties: false }, annotations: { readOnlyHint: false, untrustedContentHint: true }, async execute(input) { const manualTags = Array.isArray(input?.tags) ? input.tags.slice(0, 8) : []; const record = input?.url ? await processLink(input.url, manualTags) : await processPlainText(input?.text || "", manualTags); await putRecord(record); if (state.session) await syncRecords([record]); state.records = (await allRecords()).map(normaliseRecord); renderNavigation(); render(); return { id: record.id, category: record.category, subcategory: record.subcategory, saved: true }; } }); context.registerTool({ name: "search_archive", title: "Search the archive", description: "Search saved ideas without changing them.", inputSchema: { type: "object", properties: { query: { type: "string" } }, required: ["query"], additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: true }, async execute(input) { const q = String(input.query).toLowerCase(); return { matches: state.records.filter(record => [record.title, record.quote, record.relevance, record.resonance, ...(record.tags || [])].join(" ").toLowerCase().includes(q)).slice(0, 20).map(record => ({ id: record.id, title: record.title, category: record.category, quote: record.quote })) }; } }); } catch { /* optional browser integration */ } }

$$('[data-source]').forEach(button => button.onclick = () => { state.source = button.dataset.source; $$('[data-source]').forEach(item => item.classList.toggle("active", item === button)); render(); });
$$('[data-mobile-view]').forEach(button => button.onclick = () => setView(button.dataset.mobileView));
$("#searchInput").oninput = event => { state.query = event.target.value; render(); };
$("#sortButton").onclick = event => { state.newest = !state.newest; event.currentTarget.textContent = state.newest ? "Newest" : "Oldest"; render(); };
[$("#openCapture"), $("#emptyCapture"), $("#mobileCapture")].forEach(button => button.onclick = openCapture);
[$("#closeCapture"), $("#cancelCapture")].forEach(button => button.onclick = closeCapture);
els.form.onsubmit = saveCapture;
els.files.onchange = event => { state.files = [...event.target.files].slice(0, 20); $("#fileCount").textContent = state.files.length ? `${state.files.length} selected` : ""; };
$("#imageDrop").ondragover = event => { event.preventDefault(); event.currentTarget.classList.add("dragging"); };
$("#imageDrop").ondragleave = event => event.currentTarget.classList.remove("dragging");
$("#imageDrop").ondrop = event => { event.preventDefault(); event.currentTarget.classList.remove("dragging"); state.files = [...event.dataTransfer.files].filter(file => file.type.startsWith("image/")).slice(0, 20); $("#fileCount").textContent = state.files.length ? `${state.files.length} selected` : ""; };
[$("#closeDetail"), $("#dismissDetail")].forEach(button => button.onclick = () => els.detail.close());
$("#deleteRecord").onclick = async () => { if (!state.currentId) return; await removeRecord(state.currentId); if (state.session) await cloudRequest(`/rest/v1/fragments?id=eq.${encodeURIComponent(state.currentId)}`, { method: "DELETE" }); state.records = (await allRecords()).map(normaliseRecord); els.detail.close(); renderNavigation(); render(); notify("Removed from archive"); };
[$("#openAccount"), $("#mobileAccount")].forEach(button => button.onclick = () => { els.more.close(); renderAccount(); els.account.showModal(); });
$("#closeAccount").onclick = () => els.account.close(); $("#accountForm").onsubmit = event => { event.preventDefault(); authenticate("signin"); }; $("#createAccount").onclick = () => authenticate("signup"); $("#signOut").onclick = () => { saveSession(null); els.account.close(); notify("Signed out on this device"); };
[$("#openData"), $("#mobileData")].forEach(button => button.onclick = () => { els.more.close(); updateStorageLine(); els.data.showModal(); });
$("#closeData").onclick = () => els.data.close(); $("#exportData").onclick = exportArchive; $("#importData").onchange = event => importArchive(event.target.files[0]);
$("#mobileMore").onclick = () => els.more.showModal(); $("#closeMore").onclick = () => els.more.close();
document.addEventListener("keydown", event => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); $("#searchInput").focus(); } if (event.key === "Escape" && els.capture.open) closeCapture(); });

async function init() { try { let records = await allRecords(); const seedFlag = localStorage.getItem(ARTICLE_LIBRARY_VERSION); if (seedFlag !== "seeded" || !records.some(record => record.curated)) { const ids = new Set(records.map(record => record.id)); for (const article of window.CURATED_ARTICLES || []) if (!ids.has(article.id)) await putRecord(normaliseRecord(article)); localStorage.setItem(ARTICLE_LIBRARY_VERSION, "seeded"); records = await allRecords(); } for (const source of records) { const record = normaliseRecord(source); if (record.category !== source.category || record.subcategory !== source.subcategory) await putRecord(record); } state.records = (await allRecords()).map(normaliseRecord); renderNavigation(); render(); renderAccount(); await refreshSession(); } catch { notify("This browser could not open your local archive"); } registerWebMcp(); if ("serviceWorker" in navigator) navigator.serviceWorker.register("./sw.js?v=9").catch(() => {}); }
init();
